-- theme.lua — theme/theme.toml's colors for Hyprland's Lua config. Generated by theme/retheme:
-- edit theme.toml and run that, not this file.
--
-- Every palette name, token and role is a field, the same names the shell's Theme.qml uses:
-- t.crystalBlue, t.accent, t.focus_accent. Each is bare hex, with the opacity appended for a
-- translucent token. rgba() puts one in Hyprland's syntax, optionally at another opacity, 0 to 1:
--     t.rgba(t.accent)         --> "rgba(E6C384ff)"
--     t.rgba(t.line, 0.533)    --> "rgba(54546D88)"

local t = {
    -- Palette: Kanagawa Wave.
{% for c in palette %}
    {{c.name|pad:13}} = "{{c|bare}}",
{% endfor %}
    -- Off-palette.
{% for c in extras %}
    {{c.name|pad:13}} = "{{c|bare}}",
{% endfor %}

    -- Tokens: the job each color does.
{% for c in ui %}
    {{c.name|pad:13}} = "{{c|hexa}}",{{col:35}}-- {{c|src}}
{% endfor %}

    -- Chrome roles, shared with kitty (roles.conf) and waybar (theme.css).
{% for c in roles %}
    {{c.name|pad:13}} = "{{c|hexa}}",{{col:35}}-- {{c|src}}
{% endfor %}
}

function t.rgba(hex, alpha)
    -- A misspelled name arrives as nil. Hand Hyprland a color it rejects, so it flags that one
    -- line and goes on, rather than an error that stops the rest of the config loading.
    if type(hex) ~= "string" then return "rgba(" .. tostring(hex) .. ")" end
    local a = alpha and math.floor(alpha * 255 + 0.5) or tonumber(hex:sub(7, 8), 16) or 255
    return ("rgba(%s%02x)"):format(hex:sub(1, 6), a)
end

return t
